    const A = c.a(), B = c.b(); if (!A || !B) continue;
    const a = A.getWorldPosition(V()), b = B.getWorldPosition(V());
    const out = b.clone().add(V(0.35, 0, 0));
    const mid = a.clone().lerp(out, 0.5); mid.y = 0.04;
    c.curve = new THREE.CatmullRomCurve3([a, a.clone().lerp(mid, 0.5).setY(0.05), mid, out.clone().setY(0.1), out, b]);
    const geo = new THREE.TubeGeometry(c.curve, 64, 0.03, 8);
    if (c.mesh) { c.mesh.geometry.dispose(); c.mesh.geometry = geo; }
