  for (const k of [-1, 1]) g.add(mesh(new THREE.BoxGeometry(2.0, 0.05, 0.75), std(0x1e3a8a, { m: 0.4, r: 0.3, x: { emissive: 0x1e3a8a, emissiveIntensity: 0.3 } }), k * 1.35, 0, 0));
