  Object.assign(r, makeLabel('iridiumSat', iridiumSat, V(0, 1.4, 0)));
  const pts = []; for (let i = 0; i <= 160; i++) { const a = i / 160 * Math.PI * 2; pts.push(V(ORBIT.r * Math.cos(a), ORBIT.y, ORBIT.r * Math.sin(a) + ORBIT.cz)); }
  const orb = new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), new THREE.LineDashedMaterial({ color: 0x6d5bd0, dashSize: 0.5, gapSize: 0.4, transparent: true, opacity: 0.45 }));
