/* picking */
const ray = new THREE.Raycaster(), ndc = new THREE.Vector2(); let downXY = null;
function pick(ev) {
  const r = renderer.domElement.getBoundingClientRect();
  ndc.set(((ev.clientX - r.left) / r.width) * 2 - 1, -((ev.clientY - r.top) / r.height) * 2 + 1);
  ray.setFromCamera(ndc, camera);
  const hits = ray.intersectObjects([rig, extGroup, ...(iridiumSat ? [iridiumSat] : [])], true);
  let fallback = null;
  for (const h of hits) {
    let o = h.object, vis = true, id = null;
    if (o.userData.noPick) continue;
    while (o) { if (!o.visible) vis = false; if (!id && o.userData.compId) id = o.userData.compId; o = o.parent; }
    if (!vis || !id) continue;
    if (xray && (id === 'case' || id === 'lid' || id === 'pack')) { fallback ??= id; continue; }
    return id;
  }
  return fallback;
}
renderer.domElement.addEventListener('pointerdown', e => { downXY = [e.clientX, e.clientY]; });
renderer.domElement.addEventListener('pointerup', e => {
  if (!downXY) return; const d = Math.hypot(e.clientX - downXY[0], e.clientY - downXY[1]); downXY = null;
  if (d > 6) return; const id = pick(e); if (id) select(id);
});
