    await S('wake', 900, 'GPIO edge → ESP32 leaves deep sleep (~100 µA)', async () => { coverTarget = 1; await sleep(900); });
    step('wake', 'done', 'SOS latched in flash. Works with no phone attached.');
    Object.assign(ink, { mode: 'SOS', foot: 'SOS: powering satellite modem...' }); drawInk(); setPanelLed('#ef4444');
    await S('power', 1500, '5 V boost on → I_EN high → I_BTD high (real hardware: ~25–40 s to charge supercaps and boot)');
    step('power', 'done', 'RockBLOCK booted · rbBegin() at 230400 baud');
    await S('fix', 0, 'u-blox MAX-M10S @ 0x42: GPS + Galileo + GLONASS + BeiDou', async () => {
      gnssSats.forEach((s, i) => setBeam('g' + i, () => s.position.clone(), () => tipPos('gnss'), 0x94a3b8, true)); await sleep(2000);
      gnssSats.forEach((s, i) => setBeam('g' + i, null, null, 0, false));
    });
    step('fix', 'done', `${Math.abs(lat).toFixed(5)}°${lat >= 0 ? 'N' : 'S'} ${Math.abs(lon).toFixed(5)}°${lon >= 0 ? 'E' : 'W'} · ±2 m · 11 sats`);
    ink.fix = `${Math.abs(lat).toFixed(4)}N ${Math.abs(lon).toFixed(4)}W now`; drawInk();
    await S('air', 900, 'SCD-41 0x62 · O₂ 0x73 · CO · BME280 0x77 · methane via UART');
    step('air', 'done', `O₂ ${sensVal.o2.toFixed(1)} % · CO ${Math.round(sensVal.co)} ppm · CO₂ ${Math.round(sensVal.co2)} ppm · ${sensVal.t.toFixed(0)} °C`);
    setLink(null);
    const pk = encodeSOS({ lat, lon, alt, time: Math.floor(Date.now() / 1000), hdop: 0.9, sats: 11, batt: ink.batt, status: 0x81, id: 0xACE1, text: msgText.value, o2: sensVal.o2, co: sensVal.co, co2: sensVal.co2, t: sensVal.t });
    await S('pack', 500); renderPacket(pk);
    step('pack', 'done', `${pk.bytes.length} bytes = 28 header + ${pk.bytes.length - 28} text`);
    await S('sat', 0, 'rbSendMessage(buf, len, timeout) → waiting for a satellite…', async () => {
      ink.sat = 'IRIDIUM  sending...'; drawInk(); setBeam('ir', () => tipPos('iridium'), satPos, 0xa78bfa, true);
      for (let i = 0; i < 10 && alive(); i++) { spawnDot(() => tipPos('iridium'), satPos, 0xc4b5fd, { life: 0.9 }); await sleep(250); }
    });
